  void DrawScene(){if(board!=null){board.gameObject.SetActive(false);Destroy(board.gameObject);}board=Node("Chess board");if(HomeScreen){DrawMen();DrawUI();Highlights();return;}if(!Physical){board.gameObject.AddComponent<TableCabinetVisual>().Board(Size,Size,false);for(int s=0;s<64;s++)Shape(board,ChessMove.Square(s),PrimitiveType.Cube,SquareLocal(s)-Vector3.up*.007f,new Vector3(Size/8,.006f,Size/8),(s%8+s/8)%2==0?ebony:ivory);}if(Physical&&entryPhase==1){if(setupBoardTint==null)setupBoardTint=TransparentGuide(new Color(.2f,.8f,1),.12f);for(int s=0;s<64;s++)Shape(board,"Transparent setup square",PrimitiveType.Cube,SquareLocal(s)-Vector3.up*.0005f,new Vector3(Size/8,.001f,Size/8),setupBoardTint);}for(int i=0;i<8;i++){var p=SquareLocal(i);p.z=HumanSide*(-Size*.5f-.015f);var label=Label(board,((char)('a'+i)).ToString(),p,.0015f);label.transform.localRotation=Quaternion.Euler(90,0,0);var rank=SquareLocal(i*8);rank.x=-HumanSide*(Size*.5f+.015f);var number=Label(board,(i+1).ToString(),rank,.0015f);number.transform.localRotation=Quaternion.Euler(90,0,0);}DrawBoardHandles();DrawAlignmentGuide();DrawEntryGuide();DrawMen();DrawUI();Highlights();DrawScanSquares();}
  void DrawMen(){ghostWhite.SetFloat("_Opacity",AlignmentInProgress?.28f:pieceOpacity);ghostBlack.SetFloat("_Opacity",AlignmentInProgress?.28f:pieceOpacity);if(men!=null){men.gameObject.SetActive(false);Destroy(men.gameObject);}foreach(var mesh in meshes)Destroy(mesh);meshes.Clear();men=Node("Chess pieces");Array.Clear(figures,0,figures.Length);var position=DisplayedPosition;if(HomeScreen||SelectingCorners||alignStage==11||quickCapture&&(alignStage==5||quickPhase==0&&!Playing))return;for(int s=0;s<64;s++)if(position.Board[s]!=0){var figure=ChessPieceModel.Build(men,position.Board[s],Physical?(position.Board[s]>0?ghostWhite:ghostBlack):(position.Board[s]>0?ivory:ebony),Physical?ghostWhite:gold,meshes);figure.localPosition=SquareLocal(s);figure.localScale=PieceScale(position.Board[s]);figure.localRotation*=Quaternion.Euler(0,HumanSide<0?180:0,0);figures[s]=figure;var tracked=pieceRegistry.At(Physical&&PendingAi.HasValue&&PendingAi.Value.To==s?PendingAi.Value.From:VisualMovePreview&&humanPreview.Value.To==s?humanPreview.Value.From:s);if(tracked!=null){var tag=figure.gameObject.AddComponent<ChessPhysicalPieceTag>();tag.PieceId=tracked.id;tag.PieceKind=position.Board[s];}}DrawCapturedPieces();DrawPhysicalGuides();}
