  public void ContinueLatest(){RefreshSaved();if(saved.Length==0){Message="No saved game yet. Choose NEW GAME or QUICK PLAY.";return;}HomeScreen=false;ResumeSession(saved[0].id);if(!StorageBlocked)BeginEntry(CaptureInProgress);}
  public void ToggleManual(){if(StorageBlocked||Recovering)return;ManualFallback=!ManualFallback;if(ManualFallback)Unverified=true;else if(Physical&&Vision.RequiresIdentity){Recovering=true;Vision.ResetBoard();}Version++;Vision.ClearEvidence();SaveSession("manual controls changed");DrawMen();DrawUI();}
  public void TogglePause(){if(StorageBlocked)return;Paused=!Paused;Version++;CancelGrab();Vision.ClearEvidence();SaveSession("pause changed");DrawUI();}
  public bool CanUndoLastMove {get{if(!Playing||Busy||StorageBlocked||Recovering)return false;var state=Match.Capture();int required=TwoPlayers?1:Match.Position.Side==HumanSide?2:1;return state.moves.Length>=required;}}
  public void Undo(){if(!CanUndoLastMove)return;CancelGrab();CancelHumanReview();ResetInteractionFeedback();capturePromptUntil=0;ai=null;Unverified=true;Version++;PendingAi=null;Match.Undo(TwoPlayers?1:Match.Position.Side==HumanSide?2:1);pieceRegistry=new ChessPieceRegistry();pieceRegistry.Enroll(Match.Position);selected=-1;Recovering=Physical;Vision.ResetBoard();DrawMen();DrawUI();Highlights();nextAi=Time.unscaledTime+1;SaveSession("undo; assisted session");Message=Physical?"Restore the physical board to the shown position, then use MANUAL if needed.":"Move taken back.";}
  public void HoverWorld(Vector3 world){HoverPiece(world);HoverPanel(world);PreviewAlignment(world);foreach(var b in buttons){var p=b.root.InverseTransformPoint(world);if(Mathf.Abs(p.x)<=b.radius&&Mathf.Abs(p.z)<=b.radius&&p.y>-.02f&&p.y<.055f)b.visual.Hover();}}
  public void ObserveHand(Vector3 world){var p=transform.InverseTransformPoint(world);if(Mathf.Abs(p.x)<Size*.55f&&Mathf.Abs(p.z)<Size*.55f&&p.y>-.03f&&p.y<.20f)LastHandAt=Time.realtimeSinceStartupAsDouble;}
  public void DirectPress(int id,Vector3 world){if(TryPanelPress(id,world))return;if(relocating||setupHand!=int.MinValue)return;ObserveHand(world);if(grabHand!=int.MinValue)return;HoverWorld(world);bool above=false;foreach(var b in buttons){var p=b.root.InverseTransformPoint(world);if(p.y>.035f)above=true;}if(above)armed[id]=true;if(armed.TryGetValue(id,out bool ready)&&ready&&TryButton(transform.InverseTransformPoint(world),.022f))armed[id]=false;}
  bool TryButton(Vector3 point,float depth=.045f){if(buttonBusy)return false;var world=transform.TransformPoint(point);foreach(var b in buttons){var p=b.root.InverseTransformPoint(world);if(Mathf.Abs(p.x)<=b.radius&&Mathf.Abs(p.z)<=b.radius&&p.y>=-.015f&&p.y<=depth){buttonBusy=true;b.visual.Press();sounds.Play(ChessPieceAudio.Cue.Button,b.root.position);StartCoroutine(ButtonLater(b.action));return true;}}return false;}
  IEnumerator ButtonLater(Action action){yield return new WaitForSecondsRealtime(.16f);buttonBusy=false;action();}
  public void TouchWorld(Vector3 world){if(TryPanelButton(world))return;if(relocating)return;var p=transform.InverseTransformPoint(world);if(TryButton(p))return;if(SelectingCorners){SelectBoardCorner(world);return;}if(SizingKing){int sq=SquareAt(p);if(sq>=0){kingSquare=sq;DrawMen();}return;}if(SetupReviewing){int sq=SquareAt(p);if(sq>=0){setupSelected=sq;Message=ChessMove.Square(sq)+": "+(unknownSquares[sq]?"UNKNOWN":ChessObservationGate.Piece(setupPosition.Board[sq]));}return;}if(Mathf.Abs(p.y)>.15f)return;SelectSquare(SquareAt(p));}
  int SquareAt(Vector3 p){int x=Mathf.FloorToInt(p.x*HumanSide/Size*8+4),y=Mathf.FloorToInt(p.z*HumanSide/Size*8+4);return x<0||x>7||y<0||y>7?-1:y*8+x;}
  public void SelectSquare(int square){if(editing&&square>=0&&square<64){importPosition.Board[square]=brush;DrawMen();return;}if(StorageBlocked)return;if(!Playing||Paused||SessionMenuOpen||Busy||Recovering||Match.Result!=""||square<0||Physical&&!ManualFallback)return;if(PendingAi.HasValue){if(square==PendingAi.Value.To)Play(PendingAi.Value);return;}if(!TwoPlayers&&Match.Position.Side!=HumanSide)return;var moves=Match.Position.LegalMoves();var chosen=moves.Where(m=>m.From==selected&&m.To==square&&(m.Promotion==0||m.Promotion==Promotion)).ToList();if(chosen.Count==1){Play(chosen[0]);return;}selected=Math.Sign(Match.Position.Board[square])==Match.Position.Side?square:-1;Highlights();}
  public bool PieceHeld=>grabHand!=int.MinValue;
  public bool BeginGrab(int hand,Vector3 world){if(relocating||StorageBlocked||Recovering||PendingAi.HasValue||VisualMovePreview&&!AwaitingDone||!Playing||Paused||SessionMenuOpen||Busy||grabHand!=int.MinValue||Match.Result!=""||!TwoPlayers&&Match.Position.Side!=HumanSide)return false;var p=transform.InverseTransformPoint(world);int square=PieceInteractionSquare(world);if(square<0)return false;if(AwaitingDone){if(square==humanPreview.Value.To)square=humanPreview.Value.From;else if(Math.Sign(Match.Position.Board[square])!=Match.Position.Side)return false;CancelHumanReview();}if(Math.Sign(Match.Position.Board[square])!=Match.Position.Side)return false;grabHand=hand;grabSquare=square;grabSeen=Time.unscaledTime;selected=square;var figure=figures[square];gripLocal=figure.InverseTransformPoint(world);gripLocal.x=gripLocal.z=0;gripLocal.y=Mathf.Clamp(gripLocal.y,.012f,Math.Abs(Match.Position.Board[square])==1?.046f:.065f);FollowPinch(world);sounds.Play(ChessPieceAudio.Cue.Lift,world);Highlights();return true;}
  void FollowPinch(Vector3 world){var figure=figures[grabSquare];if(figure!=null)figure.position+=world-figure.TransformPoint(gripLocal);}
  public bool UpdateGrab(int hand,Vector3 world,bool release){if(grabHand!=hand)return false;grabSeen=Time.unscaledTime;FollowPinch(world);if(!release)return true;var point=transform.InverseTransformPoint(world);int origin=grabSquare;int ply=Match.Position.Ply;grabHand=int.MinValue;releasingGrab=true;try{if(point.y>=-.03f&&point.y<=.15f){PreviewPlayerDrop(origin,SquareAt(point));}}finally{releasingGrab=false;}if(Match.Position.Ply==ply&&!VisualMovePreview){if(figures[origin]!=null)figures[origin].localPosition=SquareLocal(origin);sounds.Play(ChessPieceAudio.Cue.Return,SquareWorld(origin));}return true;}
  public void ForgetHand(int hand){if(setupHand==hand)EndSetupGrab();if(resizeHand==hand)EndBoardResize();armed.Remove(hand);if(grabHand==hand)CancelGrab();}
  void CancelGrab(){if(grabHand!=int.MinValue&&figures[grabSquare]!=null)figures[grabSquare].localPosition=SquareLocal(grabSquare);grabHand=int.MinValue;}
  public bool ApplyCameraMove(ChessMove move,int version){if(StorageBlocked||version!=Version||!Physical||ManualFallback||Paused||SessionMenuOpen||Busy||Recovering||!HandsClear||!Playing)return false;if(PendingAi.HasValue&&!PendingAi.Value.Equals(move))return false;if(!PendingAi.HasValue&&!TwoPlayers&&Match.Position.Side!=HumanSide)return false;return Play(move,true);}
  public bool Play(ChessMove move,bool camera=false,bool userConfirmed=false){if(StorageBlocked||!Playing||Paused||SessionMenuOpen||Busy||Recovering||Physical&&!Aligned||Physical&&!camera&&!ManualFallback&&!userConfirmed)return false;if(PendingAi.HasValue&&!PendingAi.Value.Equals(move))return false;var before=Match.Position.Copy();var figure=figures[move.From];if(!Match.Play(move))return false;pieceRegistry.Advance(before,move);int captured=before.Board[move.EnPassant?move.To-before.Side*8:move.To];if(captured!=0){captureTrayColor=Math.Sign(captured);capturePromptUntil=Time.unscaledTime+12;captureInstruction="Place the captured "+SideName(captured)+" "+PieceName(captured)+" in the marked "+(captured>0?"left":"right")+" gold capture-grid slot.";}CancelHumanReview();Version++;PendingAi=null;selected=-1;Message=move.ToString();if(Physical&&!camera)Unverified=true;if(!Physical)Vision.ResetBoard();if(!SaveSession(camera?"camera move":userConfirmed?"player confirmed move with DONE":"move"))return false;if(Physical){if(camera)ConfirmPlacement(move.To);if(!camera)Vision.ResetBoard();DrawMen();Highlights();DrawUI();nextAi=Time.unscaledTime+1;}else{if(!releasingGrab)sounds.Play(ChessPieceAudio.Cue.Lift,SquareWorld(move.From));Busy=true;StartCoroutine(AnimateMove(figure,move));}return true;}
  IEnumerator AnimateMove(Transform figure,ChessMove move){var start=figure!=null?figure.localPosition:SquareLocal(move.From);var end=SquareLocal(move.To);float age=0;while(age<.4f){if(!Paused)age+=Time.deltaTime;if(figure!=null)figure.localPosition=Vector3.Lerp(start,end,Mathf.SmoothStep(0,1,age/.4f))+Vector3.up*Mathf.Sin(Mathf.Clamp01(age/.4f)*Mathf.PI)*.025f;yield return null;}Busy=false;sounds.Play(ChessPieceAudio.Cue.Place,SquareWorld(move.To));DrawMen();Highlights();DrawUI();nextAi=Time.unscaledTime+.65f;}
  void Highlights(){if(marks!=null){marks.gameObject.SetActive(false);Destroy(marks.gameObject);}marks=Node("Legal move highlights");if(!Playing||HomeScreen)return;var squares=new HashSet<int>();if(selected>=0){squares.Add(selected);foreach(var m in Match.Position.LegalMoves().Where(m=>m.From==selected))squares.Add(m.To);}if(PendingAi.HasValue){squares.Add(PendingAi.Value.From);squares.Add(PendingAi.Value.To);}if(Match.LastMove.HasValue){squares.Add(Match.LastMove.Value.From);squares.Add(Match.LastMove.Value.To);}foreach(int s in squares){var tile=Shape(marks,ChessMove.Square(s)+" highlight",PrimitiveType.Quad,SquareLocal(s)+Vector3.up*(Physical?.0005f:-.002f),new Vector3(Size/8*.85f,Size/8*.85f,1),s==selected?blue:green);tile.localRotation=Quaternion.Euler(90,0,0);}}
  void Update(){if(TableLifecycle.Blocked){if(!resumeUI)OnApplicationPause(true);return;}if(resumeUI){resumeUI=false;if(relocating)EndRelocation();DrawUI();}UpdateStandardEntry();UpdateAlignmentViewGuide();UpdateInteractionFeedback();UpdateAlignmentMessages();UpdatePhysicalGuides();UpdateScanFeedback();if(setupHand!=int.MinValue&&Time.unscaledTime-setupSeen>.3f)EndSetupGrab();UpdateHandleFeedback();if(turnHeading!=null)turnHeading.text=TurnTitle;if(grabHand!=int.MinValue&&Time.unscaledTime-grabSeen>.3f)CancelGrab();if(ai!=null&&ai.IsCompleted){var task=ai;ai=null;if(task.IsFaulted){Message="AI unavailable. Restart or use two-player mode.";}else if(!StorageBlocked&&Playing&&Version==aiVersion&&Match.Position==aiPosition&&!Paused&&!SessionMenuOpen&&!Busy&&!Recovering){if(Physical){PendingAi=task.Result;Version++;Vision.ClearEvidence();SaveSession("AI move proposed; awaiting real pieces");Message="Move the AI piece: "+PendingAi;DrawMen();Highlights();DrawUI();}else Play(task.Result);}}
   if(!StorageBlocked&&Playing&&!Physical&&!Paused&&!SessionMenuOpen&&!Busy&&!Recovering&&PendingAi.HasValue)Play(PendingAi.Value);
   if(!StorageBlocked&&Playing&&!Paused&&!SessionMenuOpen&&!Busy&&!Recovering&&Match.Result==""&&!TwoPlayers&&Match.Position.Side!=HumanSide&&!PendingAi.HasValue&&ai==null&&Time.unscaledTime>=nextAi){aiVersion=Version;aiPosition=Match.Position;var copy=aiPosition.Copy();ai=Task.Run(()=>ChessAi.Choose(copy));}
   if(entryPhase>0&&!standardMenu&&status!=null){status.text=EntryInstructions;}
   if(status!=null&&!HomeScreen&&!AlignmentMessageView&&entryPhase==0){string header=!Playing?"LIVING TABLE / CHESS":Match.Result!=""?Match.Result:"CHESS - "+SideName(Match.Position.Side)+" to move"+(Match.Position.InCheck(Match.Position.Side)?" - CHECK":"");string seats=Playing&&!GameOver?"\nYou: "+SideName(HumanSide)+" | "+(TwoPlayers?"Human":"AI")+": "+SideName(-HumanSide)+" | "+(Physical?"Real board":"Virtual board"):"";status.text=VirtualSafetyOpen?WrapStatus(VirtualSafetyText):companionOpen?WrapStatus(companionText):WrapStatus((GameOver?"":header)+seats+"\n"+(standardMenu?"MENU — return to play, change panel size, or leave the table.":alignStage==6?Vision.Status:alignStage>0?Message:TurnGuidance)+(Playing?"\n"+(Unverified?"Manual / imported history":"Session saved") :""));}
#if ENABLE_INPUT_SYSTEM
   if(desktop&&Mouse.current!=null&&Camera.main!=null){var ray=Camera.main.ScreenPointToRay(Mouse.current.position.ReadValue());if(PointAtMenu(ray,Mouse.current.leftButton.wasPressedThisFrame)&&Mouse.current.leftButton.wasPressedThisFrame)return;var buttonPlane=new Plane(transform.up,transform.TransformPoint(new Vector3(0,.025f,0)));if(buttonPlane.Raycast(ray,out float bd)){var bp=ray.GetPoint(bd);HoverWorld(bp);if(Mouse.current.leftButton.wasPressedThisFrame&&TryButton(transform.InverseTransformPoint(bp)))return;}var plane=new Plane(transform.up,transform.position);if(plane.Raycast(ray,out float d)){var point=ray.GetPoint(d);HoverWorld(point);if(Mouse.current.leftButton.wasPressedThisFrame)TouchWorld(point);}}
#endif
  }
  static string WrapStatus(string text){var lines=new List<string>();foreach(var paragraph in text.Split('\n')){string line="";foreach(var word in paragraph.Split(' ')){if(line.Length+word.Length+1>42){lines.Add(line);line="";}line+=(line.Length==0?"":" ")+word;}lines.Add(line);}return string.Join("\n",lines);}
  public void PrepareRoomRecovery(){EndBoardResize();calibration?.Cancel();calibrationBusy=false;alignStage=0;StopAllCoroutines();Busy=buttonBusy=false;CancelGrab();companionRequest++;companion?.Cancel();companionOpen=false;sessionMenu=false;DrawMen();Highlights();}
  public void BeginRelocation(){if(relocating||BoardPoseLocked)return;calibration?.Cancel();calibrationBusy=false;proposedSizes=null;alignStage=0;SaveSession("board moving");previousPause=Paused;Paused=true;relocating=true;Version++;CancelGrab();Vision.ClearEvidence();DrawScene();}
  public void EndRelocation(){if(!relocating)return;if(entryPhase>0){relocating=false;Paused=Playing;alignStage=entryPhase==1?13:entryPhase==2?1:14;DrawScene();return;}relocating=false;Paused=previousPause;if(Physical){Aligned=false;Recovering=Playing;alignStage=3;Message="Check the adjusted grid. ACCEPT BOARD confirms this fit; no game move changed.";}DrawScene();SaveSession("board relocated");if(Physical)RefineAdjustedBoard();}
  void OnEnable(){ApplyRoom();}
  void OnDisable(){if(!gameObject.activeSelf&&panel!=null)panel.gameObject.SetActive(false);EndBoardResize();SaveSession("hidden");Version++;CancelGrab();Vision?.ClearEvidence();}
  bool resumeUI;
  void OnApplicationPause(bool pause){if(pause){resizeHand=int.MinValue;resizeCorner=-1;calibration?.Cancel();if(Playing){if(relocating)previousPause=true;Paused=true;Version++;CancelGrab();SaveSession("suspended");}resumeUI=true;}}
  void OnDestroy(){if(panel!=null)Destroy(panel.gameObject);foreach(var m in materials)Destroy(m);foreach(var mesh in meshes)Destroy(mesh);foreach(var mesh in guideMeshes)Destroy(mesh);}
 }
}
